namespace RegistrationService.Data;public static class DatabaseInitializer{public static async Task InitializeAsync(IServiceProvider services){using var scope=services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<RegistrationDbContext>();var tries=0;while(true){try{await db.Database.EnsureCreatedAsync();break;}catch when(++tries<40){await Task.Delay(TimeSpan.FromSeconds(3));}}}}